import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import Button from '../components/Button';
import ProgressBar from '../components/ProgressBar';

export default function RoadmapPage() {
  const { name } = useParams();
  const navigate = useNavigate();
  const [roadmapPlan, setRoadmapPlan] = useState([]);
  const [domain, setDomain] = useState('');
  const [timeline, setTimeline] = useState('');

  useEffect(() => {
    const rawPlan = localStorage.getItem('roadmapPlan');
    const selectedDomain = localStorage.getItem('selectedDomain') || name || 'Ai And Ml';
    
    // ✅ Fetch the timeline generated in ProfilePage.js
    const savedTimeline = localStorage.getItem('timeline') || '3 months';

    if (rawPlan) {
      try {
        const parsedPlan = JSON.parse(rawPlan);
        if (Array.isArray(parsedPlan)) {
          setRoadmapPlan(parsedPlan);
        }
      } catch (e) {
        console.error("Local storage parsing error", e);
      }
    }
    setDomain(selectedDomain);
    setTimeline(savedTimeline);
  }, [name]);

  const handleStartLearning = () => navigate('/tasks');
  const getDomainTitle = () => domain.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');

  // 🛠️ FIX: Convert "X months" or "X years" string to total days
  const getTimelineInDays = () => {
    if (!timeline) return 0;
    const numericValue = parseInt(timeline.match(/\d+/) || 0); // Extracts the number from the string
    
    if (timeline.toLowerCase().includes('year')) {
      return numericValue * 365; // Convert years to days
    }
    return numericValue * 30; // Convert months to days
  };

  // ✅ Updated totalDays using your Profile Page timeline
  const totalDays = getTimelineInDays();
  
  // Track individual task completion for accurate phase percentages
  const completedTaskLabels = JSON.parse(localStorage.getItem("completedTasks") || "[]");
  const allTasksFlat = roadmapPlan.flat();
  
  // Calculate overall progress based on tasks vs target timeline
  const overallProgress = allTasksFlat.length > 0 
    ? Math.round((allTasksFlat.filter(t => completedTaskLabels.includes(t)).length / allTasksFlat.length) * 100) 
    : 0;

  const completedDaysCount = JSON.parse(localStorage.getItem("completedDays") || "[]").length;
  const remainingDays = Math.max(totalDays - completedDaysCount, 0);

  const getPhaseProgress = (phaseTasks) => {
    if (!phaseTasks || phaseTasks.length === 0) return 0;
    const completedInPhase = phaseTasks.filter(taskLabel => completedTaskLabels.includes(taskLabel)).length;
    return Math.round((completedInPhase / phaseTasks.length) * 100);
  };

  return (
    <div className="space-y-8">
      {/* Header Section */}
      <div className="rounded-[2rem] border border-slate-300 bg-white p-8 shadow-lg">
        <h1 className="text-4xl font-bold">{getDomainTitle()} Roadmap</h1>
        <p className="mt-2 text-slate-600">
          Your personalized {timeline} path with {roadmapPlan.length} phases
        </p>
        
        <div className="mt-8 flex flex-col gap-6 lg:flex-row">
          <div className="flex-1 bg-slate-50 p-6 rounded-3xl border">
            <p className="text-xs font-bold text-slate-500 uppercase mb-2">Overall Progress</p>
            <ProgressBar label="Roadmap" value={overallProgress} />
          </div>
          <div className="bg-teal-50 p-6 rounded-3xl border text-center min-w-[150px]">
            <p className="text-xs font-bold text-teal-600 uppercase">Target Timeline</p>
            <p className="text-2xl font-black">{totalDays} Days</p>
          </div>
          <div className="bg-orange-50 p-6 rounded-3xl border text-center min-w-[150px]">
            <p className="text-xs font-bold text-orange-600 uppercase">Remaining</p>
            <p className="text-2xl font-black">{remainingDays} / {totalDays}</p>
          </div>
        </div>
      </div>

      {/* Roadmap Phases */}
      <div className="space-y-4">
        <h2 className="text-2xl font-bold px-2">📚 Learning Phases</h2>
        {roadmapPlan.map((phase, idx) => {
          const progress = getPhaseProgress(phase);
          return (
            <div key={idx} className={`rounded-[2rem] border p-8 transition-all ${progress === 100 ? 'bg-green-50 border-green-200' : 'bg-white border-slate-200'}`}>
              <div className="flex items-center gap-4 mb-6">
                <span className={`h-12 w-12 rounded-2xl flex items-center justify-center text-white font-bold ${progress === 100 ? 'bg-green-500' : 'bg-teal-500'}`}>
                  {progress === 100 ? '✓' : idx + 1}
                </span>
                <div className="flex-1">
                  <div className="flex justify-between items-center mb-1">
                    <h3 className="text-xl font-bold text-slate-800">Phase {idx + 1}</h3>
                    <span className="text-sm font-bold text-teal-600">{progress}%</span>
                  </div>
                  <ProgressBar label={`Phase ${idx+1}`} value={progress} />
                </div>
              </div>
              <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
                {phase.slice(0, 4).map((task, tIdx) => (
                  <div key={tIdx} className={`p-4 rounded-2xl border text-sm flex gap-2 ${completedTaskLabels.includes(task) ? 'bg-teal-50 border-teal-100 text-teal-800' : 'bg-slate-50 border-slate-100 text-slate-600'}`}>
                    <span className="font-bold">{completedTaskLabels.includes(task) ? '✓' : '○'}</span> {task}
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>

      <div className="flex justify-center pb-10">
        <Button onClick={() => navigate('/tasks')} className="px-12 py-4 text-xl shadow-lg hover:scale-105 transition-all">
          Continue Learning Journey 🚀
        </Button>
      </div>
    </div>
  );
}
